TLM.f("Tempora/PentEpi4-0",{"officium":"Dominica IV quæ superfuit Post Epiphaniam","rule":["Gloria","Credo","Prefatio=Trinitate","Suffr=Sanctorum;Maria3,Ecclesiæ,Papa;;"],"sections":{"Introitus":[{"k":"ref","la":"Jer 29:11; 29:12; 29:14"},{"k":"text","la":"Dicit Dóminus: Ego cógito cogitatiónes pacis, et non afflictiónis: invocábitis me, et ego exáudiam vos: et redúcam captivitátem vestram de cunctis locis."},{"k":"ref","la":"Ps 84:2"},{"k":"text","la":"Benedixísti, Dómine, terram tuam: avertísti captivitátem Jacob."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Dicit Dóminus: Ego cógito cogitatiónes pacis, et non afflictiónis: invocábitis me, et ego exáudiam vos: et redúcam captivitátem vestram de cunctis locis."}],"Oratio":[{"k":"text","la":"Deus, qui nos, in tantis perículis constitútos, pro humána scis fragilitáte non posse subsístere: da nobis salútem mentis et córporis; ut ea, quæ pro peccátis nostris pátimur, te adjuvánte vincámus."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Pauli Apóstoli ad Romános."},{"k":"ref","la":"Rom 13:8-10"},{"k":"text","la":"Fratres: Némini quidquam debeátis, nisi ut ínvicem diligátis: qui enim díligit próximum, legem implévit. Nam: Non adulterábis, Non occídes, Non furáberis, Non falsum testimónium dices, Non concupísces: et si quod est áliud mandátum, in hoc verbo instaurátur: Díliges próximum tuum sicut teípsum. Diléctio próximi malum non operátur. Plenitúdo ergo legis est diléctio."}],"Graduale":[{"k":"ref","la":"Ps 43:8-9"},{"k":"text","la":"Liberásti nos, Dómine, ex affligéntibus nos: et eos, qui nos odérunt, confudísti."},{"k":"text","la":"In Deo laudábimur tota die, et in nómine tuo confitébimur in sǽcula. Allelúja, allelúja.","mark":"V"},{"k":"ref","la":"Ps 129:1-2"},{"k":"text","la":"De profúndis clamávi ad te, Dómine: Dómine, exáudi oratiónem meam. Allelúja."}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Matthǽum."},{"k":"ref","la":"Matt 8:23-27"},{"k":"text","la":"In illo témpore: Ascendénte Jesu in navículam, secúti sunt eum discípuli ejus: et ecce, motus magnus factus est in mari, ita ut navícula operirétur flúctibus, ipse vero dormiébat. Et accessérunt ad eum discípuli ejus, et suscitavérunt eum, dicéntes: Dómine, salva nos, perímus. Et dicit eis Jesus: Quid tímidi estis, módicæ fídei? Tunc surgens, imperávit ventis et mari, et facta est tranquíllitas magna. Porro hómines miráti sunt, dicéntes: Qualis est hic, quia venti et mare obœ́diunt ei?"}],"Offertorium":[{"k":"ref","la":"Ps 129:1-2"},{"k":"text","la":"De profúndis clamávi ad te, Dómine: Dómine, exáudi oratiónem meam: de profúndis clamávi ad te, Dómine."}],"Secreta":[{"k":"text","la":"Concéde, quǽsumus, omnípotens Deus: ut hujus sacrifícii munus oblátum fragilitátem nostram ab omni malo purget semper et múniat."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Marc 11:24"},{"k":"text","la":"Amen, dico vobis, quidquid orántes pétitis, crédite, quia accipiétis, et fiet vobis."}],"Postcommunio":[{"k":"text","la":"Múnera tua nos, Deus, a delectatiónibus terrenis expédiant: et cœléstibus semper instáurent aliméntis."},{"k":"macro","name":"Per Dominum"}]},"hr":{"ba591f95b6d2e86d":{"t":"Jer 29, 11-12.14, Ps 84, 2\n(Jer 29, 11-12.14) Govori Gospodin: Ja mislim misli mira a ne ugnjetavanja. Zazvat ćete me i ja ću vas uslišiti i izbavit ću vas robove iz svih krajeva. (Ps 84, 2) Blagoslovio si, Gospodine, svoju zemlju, na dobro si okrenuo Jakovljevu sudbinu.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Jer 29, 11-12.14) Govori Gospodin: Ja mislim misli mira a ne ugnjetavanja. Zazvat ćete me i ja ću vas uslišiti i izbavit ću vas robove iz svih krajeva."},"73a6e95fc762642b":{"t":"<i>Pomolimo se</i>.\nBože, koji znaš da zbog ljudske slabosti ne možemo odolijevati tolikim pogiblima, daj nam zdravlje duše i tijela, da ono što trpimo za svoje grijehe svladamo uz tvoju pomoć.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"0f8fcefc28906709":{"t":"Rim 13, 8-10\nČitanje Poslanice bl. Pavla apostola Rimljanima. Braćo: Nikome ništa ne dugujete, osim da se ljubite među sobom, jer tko ljubi bližnjega ispunio je zakon. Uistinu: Ne učini preljuba, ne ubij, ne ukradi, ne svjedoči krivo, ne poželi, i ako ima još koja zapovijed – sve je sadržano u ovoj: »Ljubi bližnjega svoga kao samog sebe.« Ljubav ne čini zla bližnjemu. Dakle, ljubav je izvršenje zakona."},"a8b02c4b81c26ed7":{"t":"Ps 43, 8-9\nSpasio si nas, Gospodine, od naših protivnika i smeo si naše mrzitelje. U Bogu je naša slava u svako doba, i uvijek hvalimo ime tvoje.\n\nPs 129, 1-2\n<i>Aleluja</i>, <i>aleluja</i>.\nIz dubine vapijem k tebi, Gospodine. Gospodine, usliši moj glas. <i>Aleluja</i>."},"363c61b1eee0825d":{"t":"Mt 8, 23-27\nSlijedi sveto Evanđelje po Mateju. U ono vrijeme: Uđe Isus u lađu, a njegovi učenici za njim. I gle, na moru nasta velika oluja, tako da su valovi pokrivali lađu. A on je spavao. Tada njegovi učenici pristupe k njemu, probude ga i reknu mu: Gospodine, spasi nas, pogibosmo! Isus im reče: Što se strašite, malovjerni? Tada ustane, zapovjedi vjetrovima i moru, i nasta velika tišina. A ljudi su začuđeno pitali: Tko je ovaj da ga slušaju vjetrovi i more?","v":"et → ∅"},"8a9f1217916db598":{"t":"Ps 129, 1-2\nIz dubine vapijem k tebi, Gospodine. Gospodine, usliši moj glas. Iz dubine vapijem k tebi, Gospodine."},"048b98f96866c762":{"t":"Dopusti, molimo, svemogući Bože, da prikazni dar ove žrtve vazda čisti i brani našu krhku narav od svakoga zla.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"adad0f7f2fcbfa9b":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi. Gospodine, sveti Oče, svemogući vječni Bože. – Ti si s jedinorođenim Sinom tvojim i s Duhom Svetim jedan Bog, jedan Gospodin, ne u jedinstvu jedne osobe, već u Trojstvu jedine biti. Što naime po tvojoj objavi vjerujemo o tvojoj slavi, to isto bez razlike i razlučivanja vjerujemo i o tvome Sinu i o Duhu Svetome. Tako se u ispovijedanju istinitog i vjekovječnog božanstva klanjamo i vlastitosti osoba i jedinstvu biti i jednakosti veličanstva. – Koje hvale anđeli i arkanđeli, kerubini i serafini koji ne prestaju svaki dan klicati govoreći složnim glasom:"},"2a2aa3c192299041":{"t":"Mk 11, 24\nZaista vam kažem: Što god moleći zaištete, vjerujte da ćete dobiti, i bit će vam."},"96cb53c5249ebbd3":{"t":"<i>Pomolimo se</i>.\nNeka nas, Bože, tvoji darovi odvraćaju od zemaljskih užitaka i vazda krijepe nebeskom hranom.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."}}});
